import { useState } from 'react';

export default function DebugMe({ user }) {
  const [count, setCount] = useState(0);

  function handleIncrement() {
    // BUG 1: this mutates — fix it
    count = count + 1;
    setCount(count);
  }

  // BUG 2: crashes if user is null — add a guard
  return (
    <div>
      <p>Welcome, {user.name}!</p>
      <p>Count: {count}</p>
      <button onClick={handleIncrement}>Increment</button>
    </div>
  );
}
